265→// IsSetUp returns true if Entire has been set up in the current repository.
266→// This checks if .entire/settings.json exists.
267→// Use this to avoid creating files/directories in repos where Entire was never enabled.
268→func IsSetUp(ctx context.Context) bool {
269→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
270→	if err != nil {
271→		return false
272→	}
273→	_, err = os.Stat(settingsFileAbs)
274→	return err == nil
275→}
276→
277→// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
278→// This checks if .entire/settings.json exists AND has enabled: true.
279→// Use this for hooks that should be no-ops when Entire is not active.
280→func IsSetUpAndEnabled(ctx context.Context) bool {
281→	if !IsSetUp(ctx) {
282→		return false
283→	}
284→	s, err := Load(ctx)
285→	if err != nil {
286→		return false
287→	}
288→	return s.Enabled
289→}
290→
291→// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
292→// Returns false by default if settings cannot be loaded or the key is missing.
293→func IsSummarizeEnabled(ctx context.Context) bool {
294→	settings, err := Load(ctx)
295→	if err != nil {
296→		return false
297→	}
298→	return settings.IsSummarizeEnabled()
299→}
300→
301→// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
302→func (s *EntireSettings) IsSummarizeEnabled() bool {
303→	if s.StrategyOptions == nil {
304→		return false
305→	}
306→	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
307→	if !ok {
308→		return false
309→	}
310→	enabled, ok := summarizeOpts["enabled"].(bool)
311→	if !ok {
312→		return false
313→	}
314→	return enabled
315→}
316→
317→// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
318→// Returns true if push_sessions is explicitly set to false.
319→func (s *EntireSettings) IsPushSessionsDisabled() bool {
320→	if s.StrategyOptions == nil {
321→		return false
322→	}
323→	val, exists := s.StrategyOptions["push_sessions"]
324→	if !exists {
325→		return false
326→	}
327→	if boolVal, ok := val.(bool); ok {
328→		return !boolVal // disabled = !push_sessions
329→	}
330→	return false
331→}
332→
333→// IsExternalAgentsEnabled checks if external agent discovery is enabled in settings.
334→// Returns false by default if settings cannot be loaded or the key is missing.
335→func IsExternalAgentsEnabled(ctx context.Context) bool {
336→	s, err := Load(ctx)
337→	if err != nil {
338→		return false
339→	}
340→	return s.ExternalAgents
341→}
342→
343→// Save saves the settings to .entire/settings.json.
344→func Save(ctx context.Context, settings *EntireSettings) error {
345→	return saveToFile(ctx, settings, EntireSettingsFile)
346→}
347→
348→// SaveLocal saves the settings to .entire/settings.local.json.
349→func SaveLocal(ctx context.Context, settings *EntireSettings) error {
350→	return saveToFile(ctx, settings, EntireSettingsLocalFile)
351→}
352→
353→// saveToFile saves settings to the specified file path.
354→func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
355→	// Get absolute path for the file
356→	filePathAbs, err := paths.AbsPath(ctx, filePath)
357→	if err != nil {
358→		filePathAbs = filePath // Fallback to relative
359→	}
360→
361→	// Ensure directory exists
362→	dir := filepath.Dir(filePathAbs)
363→	if err := os.MkdirAll(dir, 0o750); err != nil {
364→		return fmt.Errorf("creating settings directory: %w", err)
365→	}
366→
367→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
368→	if err != nil {
369→		return fmt.Errorf("marshaling settings: %w", err)
370→	}
371→
372→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
373→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
374→		return fmt.Errorf("writing settings file: %w", err)
375→	}
376→	return nil
377→}
