  1→package strategy
  2→
  3→import (
  4→	"context"
  5→	"errors"
  6→	"fmt"
  7→	"os"
  8→	"os/exec"
  9→	"path/filepath"
 10→	"strings"
 11→	"sync"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/settings"
 14→)
 15→
 16→// Hook marker used to identify Entire CLI hooks
 17→const entireHookMarker = "Entire CLI hooks"
 18→
 19→const backupSuffix = ".pre-entire"
 20→const chainComment = "# Chain: run pre-existing hook"
 21→
 22→// gitHookNames are the git hooks managed by Entire CLI
 23→var gitHookNames = []string{"prepare-commit-msg", "commit-msg", "post-commit", "pre-push"}
 24→
 25→// ManagedGitHookNames returns the list of git hooks managed by Entire CLI.
 26→// This is useful for tests that need to manipulate hooks.
 27→func ManagedGitHookNames() []string {
 28→	return gitHookNames
 29→}
 30→
 31→// hookSpec defines a git hook's name and content template (without chain call).
 32→type hookSpec struct {
 33→	name    string
 34→	content string
 35→}
 36→
 37→// GetGitDir returns the actual git directory path by delegating to git itself.
 38→// This handles both regular repositories and worktrees, and inherits git's
 39→// security validation for gitdir references.
 40→func GetGitDir(ctx context.Context) (string, error) {
 41→	return getGitDirInPath(ctx, ".")
 42→}
 43→
 44→// hooksDirCache caches the hooks directory to avoid repeated git subprocess spawns.
 45→// Keyed by current working directory to handle directory changes.
 46→var (
 47→	hooksDirMu       sync.RWMutex
 48→	hooksDirCache    string
 49→	hooksDirCacheDir string
 50→)
 51→
 52→// GetHooksDir returns the active hooks directory path.
 53→// This respects core.hooksPath and correctly resolves to the common hooks
 54→// directory when called from a linked worktree.
 55→// The result is cached per working directory.
 56→func GetHooksDir(ctx context.Context) (string, error) {
 57→	cwd, err := os.Getwd() //nolint:forbidigo // cache key for hooks dir, same pattern as paths.WorktreeRoot()
 58→	if err != nil {
 59→		cwd = ""
 60→	}
 61→
 62→	hooksDirMu.RLock()
 63→	if hooksDirCache != "" && hooksDirCacheDir == cwd {
 64→		cached := hooksDirCache
 65→		hooksDirMu.RUnlock()
 66→		return cached, nil
 67→	}
 68→	hooksDirMu.RUnlock()
 69→
 70→	result, err := getHooksDirInPath(ctx, ".")
 71→	if err != nil {
 72→		return "", err
 73→	}
 74→
 75→	hooksDirMu.Lock()
 76→	hooksDirCache = result
 77→	hooksDirCacheDir = cwd
 78→	hooksDirMu.Unlock()
 79→
 80→	return result, nil
 81→}
 82→
 83→// ClearHooksDirCache clears the cached hooks directory.
 84→// This is primarily useful for testing when changing directories.
 85→func ClearHooksDirCache() {
 86→	hooksDirMu.Lock()
 87→	hooksDirCache = ""
 88→	hooksDirCacheDir = ""
 89→	hooksDirMu.Unlock()
 90→}
 91→
 92→// getGitDirInPath returns the git directory for a repository at the given path.
 93→// It delegates to `git rev-parse --git-dir` to leverage git's own validation.
 94→func getGitDirInPath(ctx context.Context, dir string) (string, error) {
 95→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-dir")
 96→	cmd.Dir = dir
 97→	output, err := cmd.Output()
 98→	if err != nil {
 99→		return "", errors.New("not a git repository")
100→	}
101→
102→	gitDir := strings.TrimSpace(string(output))
103→
104→	// git rev-parse --git-dir returns relative paths from the working directory,
105→	// so we need to make it absolute if it isn't already
106→	if !filepath.IsAbs(gitDir) {
107→		gitDir = filepath.Join(dir, gitDir)
108→	}
109→
110→	return filepath.Clean(gitDir), nil
111→}
112→
113→// getHooksDirInPath returns the active hooks directory for a repository at the given path.
114→// It delegates to `git rev-parse --git-path hooks` so Git resolves:
115→// - linked-worktree common hooks directory
116→// - core.hooksPath (relative or absolute)
117→func getHooksDirInPath(ctx context.Context, dir string) (string, error) {
118→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-path", "hooks")
119→	cmd.Dir = dir
120→	output, err := cmd.Output()
121→	if err != nil {
122→		return "", errors.New("not a git repository")
123→	}
124→
125→	hooksDir := strings.TrimSpace(string(output))
126→	if !filepath.IsAbs(hooksDir) {
127→		hooksDir = filepath.Join(dir, hooksDir)
128→	}
129→
130→	return filepath.Clean(hooksDir), nil
131→}
132→
133→// IsGitHookInstalled checks if all generic Entire CLI hooks are installed.
134→func IsGitHookInstalled(ctx context.Context) bool {
135→	hooksDir, err := GetHooksDir(ctx)
136→	if err != nil {
137→		return false
138→	}
139→	return isGitHookInstalledInHooksDir(hooksDir)
140→}
141→
142→// IsGitHookInstalledInDir checks if all Entire CLI hooks are installed in the given repo directory.
143→// This is useful for tests that need to check hooks without changing the working directory.
144→func IsGitHookInstalledInDir(ctx context.Context, repoDir string) bool {
145→	hooksDir, err := getHooksDirInPath(ctx, repoDir)
146→	if err != nil {
147→		return false
148→	}
149→	return isGitHookInstalledInHooksDir(hooksDir)
150→}
151→
152→// isGitHookInstalledInHooksDir checks if all hooks are installed in the given hooks directory.
153→func isGitHookInstalledInHooksDir(hooksDir string) bool {
154→	for _, hook := range gitHookNames {
155→		hookPath := filepath.Join(hooksDir, hook)
156→		data, err := os.ReadFile(hookPath) //nolint:gosec // Path is constructed from constants
157→		if err != nil {
158→			return false
159→		}
160→		if !strings.Contains(string(data), entireHookMarker) {
161→			return false
162→		}
163→	}
164→	return true
165→}
166→
167→// buildHookSpecs returns the hook specifications for all managed hooks.
168→func buildHookSpecs(cmdPrefix string) []hookSpec {
169→	return []hookSpec{
170→		{
171→			name: "prepare-commit-msg",
172→			content: fmt.Sprintf(`#!/bin/sh
173→# %s
174→%s hooks git prepare-commit-msg "$1" "$2" 2>/dev/null || true
175→`, entireHookMarker, cmdPrefix),
176→		},
177→		{
178→			name: "commit-msg",
179→			content: fmt.Sprintf(`#!/bin/sh
180→# %s
181→# Commit-msg hook: strip trailer if no user content (allows aborting empty commits)
182→%s hooks git commit-msg "$1" || exit 1
183→`, entireHookMarker, cmdPrefix),
184→		},
185→		{
186→			name: "post-commit",
187→			content: fmt.Sprintf(`#!/bin/sh
188→# %s
189→# Post-commit hook: condense session data if commit has Entire-Checkpoint trailer
190→%s hooks git post-commit 2>/dev/null || true
191→`, entireHookMarker, cmdPrefix),
192→		},
193→		{
194→			name: "pre-push",
195→			content: fmt.Sprintf(`#!/bin/sh
196→# %s
197→# Pre-push hook: push session logs alongside user's push
198→# $1 is the remote name (e.g., "origin")
199→%s hooks git pre-push "$1" || true
200→`, entireHookMarker, cmdPrefix),
201→		},
202→	}
203→}
204→
205→// InstallGitHook installs generic git hooks that delegate to `entire hook` commands.
206→// These hooks work with any strategy - the strategy is determined at runtime.
207→// If silent is true, no output is printed (except backup notifications, which always print).
208→// localDev controls whether hooks use "go run" (true) or the "entire" binary (false).
209→// absolutePath embeds the full binary path in hooks for GUI git clients.
210→// Returns the number of hooks that were installed (0 if all already up to date).
211→func InstallGitHook(ctx context.Context, silent, localDev, absolutePath bool) (int, error) {
212→	hooksDir, err := GetHooksDir(ctx)
213→	if err != nil {
214→		return 0, err
215→	}
216→
217→	if err := os.MkdirAll(hooksDir, 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
218→		return 0, fmt.Errorf("failed to create hooks directory: %w", err)
219→	}
220→
221→	cmdPrefix, err := hookCmdPrefix(localDev, absolutePath)
222→	if err != nil {
223→		return 0, err
224→	}
225→	specs := buildHookSpecs(cmdPrefix)
226→	installedCount := 0
227→
228→	for _, spec := range specs {
229→		hookPath := filepath.Join(hooksDir, spec.name)
230→		backupPath := hookPath + backupSuffix
231→		backupExists := fileExists(backupPath)
232→
233→		// Back up existing non-Entire hooks
234→		existing, existingErr := os.ReadFile(hookPath) //nolint:gosec // path is controlled
235→		if existingErr == nil && !strings.Contains(string(existing), entireHookMarker) {
236→			if !backupExists {
237→				if err := os.Rename(hookPath, backupPath); err != nil {
238→					return installedCount, fmt.Errorf("failed to back up %s: %w", spec.name, err)
239→				}
240→				fmt.Fprintf(os.Stderr, "[entire] Backed up existing %s to %s%s\n", spec.name, spec.name, backupSuffix)
241→			} else {
242→				fmt.Fprintf(os.Stderr, "[entire] Warning: replacing %s (backup %s%s already exists from a previous install)\n", spec.name, spec.name, backupSuffix)
243→			}
244→			backupExists = true
245→		}
