334→// generateChainedContent appends a chain call to the base hook content,
335→// so the pre-existing hook (backed up to .pre-entire) is called after our hook.
336→func generateChainedContent(baseContent, hookName string) string {
337→	return baseContent + fmt.Sprintf(`%s
338→_entire_hook_dir="$(dirname "$0")"
339→if [ -x "$_entire_hook_dir/%s%s" ]; then
340→    "$_entire_hook_dir/%s%s" "$@"
341→fi
342→`, chainComment, hookName, backupSuffix, hookName, backupSuffix)
343→}
