 11→func TestLoad_RejectsUnknownKeys(t *testing.T) {
 12→	// Create a temporary directory
 13→	tmpDir := t.TempDir()
 14→
 15→	// Create .entire directory
 16→	entireDir := filepath.Join(tmpDir, ".entire")
 17→	if err := os.MkdirAll(entireDir, 0755); err != nil {
 18→		t.Fatalf("failed to create .entire directory: %v", err)
 19→	}
 20→
 21→	// Create settings.json with an unknown key
 22→	settingsFile := filepath.Join(entireDir, "settings.json")
 23→	settingsContent := `{"enabled": true, "unknown_key": "value"}`
 24→	if err := os.WriteFile(settingsFile, []byte(settingsContent), 0644); err != nil {
 25→		t.Fatalf("failed to write settings file: %v", err)
 26→	}
 27→
 28→	// Initialize a git repo (required by paths.AbsPath)
 29→	if err := os.MkdirAll(filepath.Join(tmpDir, ".git"), 0755); err != nil {
 30→		t.Fatalf("failed to create .git directory: %v", err)
 31→	}
 32→
 33→	// Change to the temp directory
 34→	t.Chdir(tmpDir)
 35→
 36→	// Try to load settings - should fail due to unknown key
 37→	_, err := Load(context.Background())
 38→	if err == nil {
 39→		t.Error("expected error for unknown key, got nil")
 40→	} else if !containsUnknownField(err.Error()) {
 41→		t.Errorf("expected unknown field error, got: %v", err)
 42→	}
 43→}
