// IsSetUpAndEnabledFast checks if Entire is set up and enabled using cwd-relative
// paths only. This avoids subprocess calls (git rev-parse) and is intended for
// hooks where git sets cwd to the worktree root. Returns false if settings.json
// doesn't exist (not set up) or if enabled is false.
func IsSetUpAndEnabledFast() bool {
	settings, err := loadFromFile(EntireSettingsFile)
	if err != nil {
		return false
	}

	// Check if the file actually exists (loadFromFile returns defaults for missing files)
	if _, statErr := os.Stat(EntireSettingsFile); statErr != nil {
		return false
	}

	// Apply local overrides if they exist
	localData, localErr := os.ReadFile(EntireSettingsLocalFile) //nolint:gosec // path is constant
	if localErr == nil {
		if err := mergeJSON(settings, localData); err != nil {
			return false
		}
	}

	return settings.Enabled
}

