// extractCommandLine returns the first command invocation line from a hook script,
// skipping shebangs, comments, shell control flow (if/then/fi), and empty lines.
func extractCommandLine(hookContent string) string {
	for _, line := range strings.Split(hookContent, "\n") {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		// Skip shell control flow used by the .entire directory guard
		if strings.HasPrefix(trimmed, "if ") || trimmed == "then" || trimmed == "fi" {
			continue
		}
		return trimmed
	}
	return ""
}

