// IsSetUpAndEnabledFast checks settings using cwd-relative paths,
// avoiding the git rev-parse subprocess that IsSetUpAndEnabled requires.
func IsSetUpAndEnabledFast() bool {
	if _, err := os.Stat(EntireSettingsFile); err != nil {
		return false
	}

	settings, err := loadFromFile(EntireSettingsFile)
	if err != nil {
		return false
	}

	localData, localErr := os.ReadFile(EntireSettingsLocalFile) //nolint:gosec // path is constant
	if localErr == nil {
		if err := mergeJSON(settings, localData); err != nil {
			return false
		}
	}

	return settings.Enabled
}

